INSERT INTO monster VALUES (329,'Dragon Turtle','Dragon Turtle',NULL,'Huge','Dragon','Aquatic','12d12+60 (138 hp)','+0','20 ft. (4 squares), swim 30 ft.','25 (-2 size, +17 natural), touch 8, flat-footed 25','+12','+28','Bite +18 melee (4d6+8)','Bite +18 melee (4d6+8) and 2 claws +13 melee (2d8+4)','15 ft.','10 ft.','Breath weapon, snatch, capsize','Darkvision 60 ft., immunity to fire, sleep, and paralysis, low-light vision, scent','Fort +13, Ref +8, Will +9','Str 27, Dex 10, Con 21, Int 12, Wis 13, Cha 12','Diplomacy +3, Hide +7*, Intimidate +16, Listen +16, Search +16, Sense Motive +16, Spot +16, Survival +16 (+18 following tracks), Swim +21',NULL,'Blind-Fight, Cleave, Improved Bull Rush, Power Attack, Snatch',NULL,'Temperate aquatic','Solitary','9','Triple standard','Usually neutral','13-24 HD (Huge); 25-36 HD (Gargantuan)','-','Breath Weapon (Su), Capsize (Ex)','Dragon turtle; CR 9; Huge dragon (aquatic); HD 12d12+60; hp 138; Init +0; Spd 20 ft. (4 squares), swim 30 ft.; AC 25 (-2 size, +17 natural), touch 8, flat-footed 25; Base Atk +12; Grp +28; Atk +18 melee (4d6+8, bite); Full Atk +18 melee (4d6+8, bite) and +13 melee (2d8+4, 2 claws); Space/Reach 15 ft./10 ft.; SA Breath weapon, snatch, capsize; SQ Darkvision 60 ft., immunity to fire, sleep,  and paralysis, low-light vision, scent; AL N; SV Fort +13, Ref +8, Will +9; Str 27, Dex 10, Con 21, Int 12, Wis 13, Cha 12\n\nSkills and Feats: Diplomacy +3, Hide +7*, Intimidate +16, Listen +16, Search +16, Sense Motive +16, Spot +16, Survival +16 (+18 following tracks), Swim +21; Blind-Fight, Cleave, Improved Bull Rush, Power Attack, Snatch','\n      <div topic=\"Dragon Turtle\" level=\"2\"><p><h2>Dragon Turtle</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Dragon Turtle</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Huge Dragon (Aquatic)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>12d12+60 (138 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), swim 30 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>25 (-2 size, +17 natural), touch 8, flat-footed 25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+12/+28<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +18 melee (4d6+8)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +18 melee (4d6+8) and 2 claws +13 melee (2d8+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>15 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Breath weapon, snatch, capsize<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., immunity to fire, <i>sleep</i>,  and paralysis, low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +13, Ref +8, Will +9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 27, Dex 10, Con 21, Int 12, Wis 13, Cha 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Diplomacy +3, Hide +7*, Intimidate +16, Listen +16, Search +16, Sense Motive +16, Spot +16, Survival +16 (+18 following tracks), Swim +21<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Blind-Fight, Cleave, Improved Bull Rush, Power Attack, Snatch<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate aquatic<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Triple standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>13-24 HD (Huge); 25-36 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Its rough, deep green shell is much the same color as the deep water the monster favors, and the silver highlights that line the shell resemble light dancing on open water. The turtle\'s legs, tail, and head are a lighter green, flecked with golden highlights. An adult dragon turtle can measure from 20 to 30 feet from snout to tail, with a shell from 15 to 25 feet in diameter, and can weigh 8,000 to 32,000 pounds.</p><p>Dragon turtles speak Aquan, Draconic, and Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Dragon turtles are fierce fighters and generally attack any creature that threatens their territory or looks like a potential meal.</p><div topic=\"Breath Weapon\" level=\"8\"><p><b>Breath Weapon (Su):</b> Cloud of superheated steam 20 feet high, 25 feet wide, and 50 feet long, once every 1d4 rounds, damage 12d6 fire, Reflex DC 21 half; effective both on the surface and underwater. The save DC is Constitution-based.</p>\n</div><div topic=\"Capsize\" level=\"8\"><p><b>Capsize (Ex):</b> A submerged dragon turtle that surfaces under a boat or ship less than 20 feet long capsizes the vessel 95% of the time. It has a 50% chance to capsize a vessel from 20 to 60 feet long and a 20% chance to capsize one over 60 feet long.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A dragon turtle has a +8 racial bonus on any Swim check to perform some special action or avoid a hazard. It can always choose to take 10 on a Swim check, even if distracted or endangered.</p><p>It can use the run action while swimming, provided it swims in a straight line.</p><p>*Dragon turtles have a +8 racial bonus on Hide checks when submerged.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersDr-Dw');
INSERT INTO monster VALUES (330,'Dragonne','Dragonne',NULL,'Large','Magical Beast',NULL,'9d10+27 (76 hp)','+6','40 ft. (8 squares), fly 30 ft. (poor)','18 (-1 size, +2 Dex, +7 natural), touch 11, flat-footed 16','+9','+17','Bite +12 melee (2d6+4)','Bite +12 melee (2d6+4) and 2 claws +7 melee (2d4+2)','10 ft.','5 ft.','Pounce, roar','Darkvision 60 ft., low-light vision, scent','Fort +9, Ref +8, Will +4','Str 19, Dex 15, Con 17, Int 6, Wis 12, Cha 12','Listen +11, Spot +11',NULL,'Blind-Fight, Combat Reflexes, Improved Initiative, Track',NULL,'Temperate deserts','Solitary, pair, or pride (5-10)','7','Double standard','Usually neutral','10-12 HD (Large); 13-27 HD (Huge)','+4 (cohort)','Pounce (Ex), Roar (Su)','Dragonne; CR 7; Large magical beast; HD 9d10+27; hp 76; Init +6; Spd 40 ft. (8 squares), fly 30 ft. (poor); AC 18 (-1 size, +2 dex, +7 natural), touch 11, flat-footed 16; Base Atk +9; Grp +17; Atk +12 melee (2d6+4, bite); Full Atk +12 melee (2d6+4, bite) and +7 melee (2d4+2, 2 claws); Space/Reach 10 ft./5 ft.; SA Pounce, roar; SQ Darkvision 60 ft., low-light vision, scent; AL N; SV Fort +9, Ref +8, Will +4; Str 19, Dex 15, Con 17, Int 6, Wis 12, Cha 12\n\nSkills and Feats: Listen +11, Spot +11; Blind-Fight, Combat Reflexes, Improved Initiative, Track','\n      <div topic=\"Dragonne\" level=\"2\"><p><h2>Dragonne</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Dragonne</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d10+27 (76 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares), fly 30 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (-1 size, +2 Dex, +7 natural), touch 11, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+9/+17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +12 melee (2d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +12 melee (2d6+4) and 2 claws +7 melee (2d4+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Pounce, roar<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +9, Ref +8, Will +4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 19, Dex 15, Con 17, Int 6, Wis 12, Cha 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +11, Spot +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Blind-Fight, Combat Reflexes, Improved Initiative, Track<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate deserts<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or pride (5-10)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Double standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-12 HD (Large); 13-27 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4 (cohort)<br/></td>\n\n</tr>\n</table><p>A dragonne possesses huge claws and fangs, and large eyes, usually the color of its scales. A dragonne is about 12 feet long and weighs about 700 pounds.</p><p>Dragonnes speak Draconic.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A dragonne\'s wings are useful only for short flights, carrying the creature for 10 to 30 minutes at a time. Nevertheless, it uses its wings effectively in battle. If opponents attempt to charge or encircle it, the dragonne simply takes to the air and finds a more defensible position.</p><div topic=\"Pounce\" level=\"8\"><p><b>Pounce (Ex):</b> If a dragonne charges, it can make a full attack in the same round.</p>\n</div><div topic=\"Roar\" level=\"8\"><p><b>Roar (Su):</b> A dragonne can loose a devastating roar every 1d4 rounds. All creatures except dragonnes within 120 feet must succeed on a DC 15 Will save or become fatigued. Those within 30 feet who fail their saves become exhausted. The save DC is Charisma-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Dragonnes have a +4 racial bonus on Listen and Spot checks.</p>\n</div><div topic=\"Carrying Capacity\" level=\"8\"><p><b>Carrying Capacity:</b> A light load for a dragonne is up to 348 pounds; a medium load, 349-699 pounds, and a heavy load, 700-1,050 pounds.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersDr-Dw');
INSERT INTO monster VALUES (331,'Drider','Drider',NULL,'Large','Aberration',NULL,'6d8+18 (45 hp)','+2','30 ft. (6 squares), climb 15 ft.','17 (-1 size, +2 Dex, +6 natural), touch 11, flat-footed 15','+4','+10','Dagger +5 melee (1d6+2/19-20) or bite +6 melee (1d4+1 plus poison) or shortbow +5 ranged (1d8/x3)','2 daggers +3 melee (1d6+2/19-20, 1d6+1/19-20) and bite +1 melee (1d4+1 plus poison); or shortbow +5 ranged (1d8/x3)','10 ft.','5 ft.','Spells, spell-like abilities, poison','Darkvision 60 ft., spell resistance 17','Fort +5, Ref +4, Will +8','Str 15, Dex 15, Con 16, Int 15, Wis 16, Cha 16','Climb +14, Concentration +9, Hide +10, Listen +9, Move Silently +12, Spot +9',NULL,'Combat Casting, Two-Weapon Fighting, Weapon Focus (bite)',NULL,'Underground','Solitary, pair, or troupe (1-2 plus 7-12 Medium monstrous spiders)','7','Double standard','Always chaotic evil','By character class','+4','Poison (Ex)','Drider; CR 7; Large aberration; HD 6d8+18; hp 45; Init +2; Spd 30 ft. (6 squares), climb 15 ft.; AC 17 (-1 size, +2 dex, +6 natural), touch 11, flat-footed 15; Base Atk +4; Grp +10; Atk +5 melee (1d6+2/19-20, dagger) or +6 melee (1d4+1 plus poison, bite) or +5 ranged (1d8/x3, shortbow); Full Atk +3 melee (1d6+2/19-20, 1d6+1/19-20, 2 daggers) and +1 melee (1d4+1 plus poison, bite) or +5 ranged (1d8/x3, shortbow); Space/Reach 10 ft./5 ft.; SA Spells, spell-like abilities, poison; SQ Darkvision 60 ft., spell resistance 17; AL CE; SV Fort +5, Ref +4, Will +8; Str 15, Dex 15, Con 16, Int 15, Wis 16, Cha 16\n\nSkills and Feats: Climb +14, Concentration +9, Hide +10, Listen +9, Move Silently +12, Spot +9; Combat Casting, Two-Weapon Fighting, Weapon Focus (bite)','\n      <div topic=\"Drider\" level=\"2\"><p><h2>Drider</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Drider</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Aberration<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d8+18 (45 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares), climb 15 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (-1 size, +2 Dex, +6 natural), touch 11, flat-footed 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Dagger +5 melee (1d6+2/19-20) or bite +6 melee (1d4+1 plus poison) or shortbow +5 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 daggers +3 melee (1d6+2/19-20, 1d6+1/19-20) and bite +1 melee (1d4+1 plus poison); or shortbow +5 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Spells, spell-like abilities, poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., spell resistance 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +4, Will +8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 15, Con 16, Int 15, Wis 16, Cha 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Climb +14, Concentration +9, Hide +10, Listen +9, Move Silently +12, Spot +9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Combat Casting, Two-Weapon Fighting, Weapon Focus (bite)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or troupe (1-2 plus 7-12 Medium monstrous spiders)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Double standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n</table><p>Driders speak Elven, Common, and Undercommon.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Driders seldom pass up an opportunity to attack other creatures, especially from ambush. They usually begin with a spell assault and often levitate out of the enemy\'s reach.</p><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 16, initial and secondary damage 1d6 Str. The save DC is Constitution based.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> 1/day-<i>dancing lights</i> (DC 13), <i>clairaudience/clairvoyance</i>,  <i>darkness</i>,  <i>detect good</i>,  <i>detect law</i>,  <i>detect magic</i>,  <i>dispel magic</i>,  <i>faerie fire</i>,  <i>levitate</i>,  <i>suggestion</i> (DC 16). Caster level 6th. The save DCs are Charisma-based.</p>\n</div><div topic=\"Spells\" level=\"8\"><p><b>Spells:</b> Driders cast spells as 6th-level clerics, wizards, or sorcerers. Drider clerics can choose from the following domains: Chaos, Destruction, Evil, and Trickery. The typical spells prepared shown here are for a drider sorcerer.</p><p><i>Typical Sorcerer Spells Known</i> (6/7/6/4, base save DC 13 + spell level): 0-<i>daze</i>,  <i>detect magic</i>,  <i>ghost sound</i>,  <i>mage hand</i>,  <i>ray of frost</i>,  <i>read magic</i>,  <i>resistance</i>; 1st-<i>mage armor</i>,  <i>magic missile</i>,  <i>ray of enfeeblement</i>,  <i>silent image</i>; 2nd- <i>invisibility</i>,  <i>web</i>; 3rd-<i>lightning bolt</i>.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A drider has a +4 racial bonus on Hide and Move Silently checks. It has a +8 racial bonus on Climb checks and can always choose to take 10 on a Climb check, even if rushed or threatened.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersDr-Dw');
INSERT INTO monster VALUES (332,'Dryad','Dryad',NULL,'Medium','Fey',NULL,'4d6 (14 hp)','+4','30 ft. (6 squares)','17 (+4 Dex, +3 natural), touch 14, flat-footed 13','+2','+2','Dagger +6 melee (1d4/19-20) or masterwork longbow +7 ranged (1d8/x3)','Dagger +6 melee (1d4/19-20) or masterwork longbow +7 ranged (1d8/x3)','5 ft.','5 ft.','Spell-like abilities','Damage reduction 5/cold iron, tree dependent, wild empathy','Fort +3, Ref +8, Will +6','Str 10, Dex 19, Con 11, Int 14, Wis 15, Cha 18','Escape Artist +11, Handle Animal +11, Hide +11, Knowledge (nature) +11, Listen +9, Move Silently +11, Ride +6, Spot +9, Survival +9, Use Rope +4 (+6 with bindings)',NULL,'Great Fortitude, Weapon Finesse',NULL,'Temperate forests','Solitary or grove (4-7)','3','Standard','Usually chaotic good','By character class','-','Tree Dependent (Su), Wild Empathy (Ex)','Dryad; CR 3; Medium fey; HD 4d6; hp 14; Init +4; Spd 30 ft. (6 squares); AC 17 (+4 dex, +3 natural), touch 14, flat-footed 13; Base Atk +2; Grp +2; Atk +6 melee (1d4/19-20, dagger) or +7 ranged (1d8/x3, masterwork longbow); Full Atk +6 melee (1d4/19-20, dagger) or +7 ranged (1d8/x3, masterwork longbow); Space/Reach 5 ft./5 ft.; SA Spell-like abilities; SQ Damage reduction 5/cold iron, tree dependent, wild empathy; AL CG; SV Fort +3, Ref +8, Will +6; Str 10, Dex 19, Con 11, Int 14, Wis 15, Cha 18\n\nSkills and Feats: Escape Artist +11, Handle Animal +11, Hide +11, Knowledge (nature) +11, Listen +9, Move Silently +11, Ride +6, Spot +9, Survival +9, Use Rope +4 (+6 with bindings); Great Fortitude, Weapon Finesse','\n      <div topic=\"Dryad\" level=\"2\"><p><h2>Dryad</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Dryad</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Fey<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d6 (14 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (+4 Dex, +3 natural), touch 14, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Dagger +6 melee (1d4/19-20) or masterwork longbow +7 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Dagger +6 melee (1d4/19-20) or masterwork longbow +7 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Damage reduction 5/cold iron, tree dependent, wild empathy<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +8, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 19, Con 11, Int 14, Wis 15, Cha 18<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Escape Artist +11, Handle Animal +11, Hide +11, Knowledge (nature) +11, Listen +9, Move Silently +11, Ride +6, Spot +9, Survival +9, Use Rope +4 (+6 with bindings)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Great Fortitude, Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or grove (4-7)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually chaotic good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A dryad\'s delicate features are much like a female elf\'s, though her flesh is like bark or fine wood, and her hair is like a canopy of leaves that changes color with the seasons.</p><p>Although they are generally solitary, up to seven dryads have been encountered in one place on rare occasions.</p><p>Dryads speak Common, Elven, and Sylvan.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Shy, intelligent, and resolute, dryads are as elusive as they are alluring-they avoid physical combat and are rarely seen unless they wish to be. If threatened, or in need of an ally, a dryad uses <i>charm person</i> or <i>suggestion</i>,  attempting to gain control of the attacker(s) who could help the most against the rest. Any attack on her tree, however, provokes the dryad into a frenzied defense.</p><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> At will-<i>entangle</i> (DC 13), <i>speak with plants</i>,  <i>tree shape</i>; 3/day- <i>charm person</i> (DC 13), <i>deep slumber</i> (DC 15), <i>tree stride</i>; 1/day-<i>suggestion</i> (DC 15). Caster level 6th. The save DCs are Wisdom-based.</p>\n</div><div topic=\"Tree Dependent\" level=\"8\"><p><b>Tree Dependent (Su):</b> Each dryad is mystically bound to a single, enormous oak tree and must never stray more than 300 yards from it. Any who do become ill and die within 4d6 hours. A dryad\'s oak does not radiate magic.</p>\n</div><div topic=\"Wild Empathy\" level=\"8\"><p><b>Wild Empathy (Ex):</b> This power works like the druid\'s wild empathy class feature, except that the dryad has a +6 racial bonus on the check.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersDr-Dw');
INSERT INTO monster VALUES (333,'Dwarf','Dwarf, 1st-Level Warrior',NULL,'Medium','Humanoid','Dwarf','1d8+2 (6 hp)','+0','20 ft. in scale mail (4 squares); base speed 20 ft.','16 (+4 scale mail, +2 heavy shield), touch 10, flat-footed 16','+1','+2','Dwarven waraxe +3 melee (1d10+1/x3) or shortbow +1 ranged (1d6/x3)','Dwarven waraxe +3 melee (1d10+1/x3) or shortbow +1 ranged (1d6/x3)','5 ft.','5 ft.','Dwarf traits','Darkvision 60 ft., dwarf traits','Fort +4*, Ref +0*, Will -1*','Str 13, Dex 11, Con 14, Int 10, Wis 9, Cha 6','Appraise +2, Craft (blacksmithing) +2, Craft (stonemasonry) +2, Listen +2, Spot +2',NULL,'Weapon Focus (dwarven waraxe)',NULL,'Temperate mountains\n(Deep: Underground)','Team (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or clan (30-100 plus 30% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)','\"','Standard coins; double goods; standard items','Often lawful good\n(Deep: Usually lawful neutral or neutral)','By character class','+0','Dwarf Traits (Ex)','1st-level warrior dwarf; CR \"; Medium humanoid (dwarf); HD 1d8+2; hp 6; Init +0; Spd 20 ft. in scale mail (4 squares); base speed 20 ft.; AC 16 (+4 scale mail, +2 heavy shield), touch 10, flat-footed 16; Base Atk +1; Grp +2; Atk +3 melee (1d10+1/x3, dwarven waraxe) or +1 ranged (1d6/x3, shortbow); Full Atk +3 melee (1d10+1/x3, dwarven waraxe) or +1 ranged (1d6/x3, shortbow); Space/Reach 5 ft./5 ft.; SA Dwarf traits; SQ Darkvision 60 ft., dwarf traits; AL LG; SV Fort +4*, Ref +0*, Will -1*; Str 13, Dex 11, Con 14, Int 10, Wis 9, Cha 6\n\nSkills and Feats: Appraise +2, Craft (blacksmithing) +2, Craft (stonemasonry) +2, Listen +2, Spot +2; Weapon Focus (dwarven waraxe)','\n      <div topic=\"Dwarf\" level=\"2\"><p><h2>Dwarf</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Dwarf, 1st-Level Warrior</b><br/></td> \n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Humanoid (Dwarf)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+2 (6 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. in scale mail (4 squares); base speed 20 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>16 (+4 scale mail, +2 heavy shield), touch 10, flat-footed 16<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/+2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Dwarven waraxe +3 melee (1d10+1/x3) or shortbow +1 ranged (1d6/x3)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Dwarven waraxe +3 melee (1d10+1/x3) or shortbow +1 ranged (1d6/x3)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Dwarf traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., dwarf traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +4*, Ref +0*, Will -1*<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 13, Dex 11, Con 14, Int 10, Wis 9, Cha 6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Appraise +2, Craft (blacksmithing) +2, Craft (stonemasonry) +2, Listen +2, Spot +2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Focus (dwarven waraxe)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate mountains<br/>\n(Deep: Underground)<br/></td> \n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Team (2-4), squad (11-20 plus 2 3rd-level sergeants and 1 leader of 3rd-6th level), or clan (30-100 plus 30% noncombatants plus 1 3rd-level sergeant per 10 adults, 5 5th-level lieutenants, and 3 7th-level captains)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>\"<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard coins; double goods; standard items<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Often lawful good<br/>\n(Deep: Usually lawful neutral or neutral)<br/></td> \n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>By character class<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+0<br/></td>\n\n\n</tr>\n</table><p>Dwarves favor earth tones in their clothing and prefer simple and functional garb. The skin can be very dark, but it is always some shade of tan or brown. Hair color can be black, gray, or brown. Dwarves average 4 feet tall and weigh as much as adult humans.</p><p>Dwarves speak Dwarven. Most who travel outside dwarven lands (as traders, mercenaries, or adventurers) know the Common tongue, while warriors in the dwarven cities usually learn Goblin to better interrogate and spy on those evil denizens of the deep caves.</p><p>Most dwarves encountered outside their home are warriors.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Dwarves are experts in combat, effectively using their environment and executing well-planned group attacks. They rarely use magic in fights, since they have few wizards or sorcerers (but dwarven clerics throw themselves into battle as heartily as their fellow warriors). If they have time to prepare, they may build deadfalls or other traps involving stone. In addition to the dwarven waraxe and thrown hammer, dwarves also use warhammers, picks, shortbows, heavy crossbows, and maces.</p><div topic=\"Dwarf Traits\" level=\"8\"><p><b>Dwarf Traits (Ex):</b> Dwarves possess the following racial traits.</p><ul>\n <li>+2 Constitution, -2 Charisma.</li>\n <li>Medium size.</li>\n</ul><p>-A dwarf\'s base land speed is 20 feet. However, dwarves can move at this speed even when wearing medium or heavy armor or when carrying a medium or heavy load.</p><ul>\n <li>Darkvision out to to 60 feet.</li>\n <li>Stonecunning: This ability grants a dwarf a +2 racial bonus on Search checks to notice unusual stonework, such as sliding walls, stonework traps, new construction (even when built to match the old), unsafe stone surfaces, shaky stone ceilings, and the like. Something that isn\'t stone but that is disguised as stone also counts as unusual stonework. A dwarf who merely comes within 10 feet of unusual stonework can make a Search check as if he were actively searching, and a dwarf can use the Search skill to find stonework traps as a rogue can. A dwarf can also intuit depth, sensing his approximate depth underground as naturally as a human can sense which way is up. Dwarves have a sixth sense about stonework, an innate ability that they get plenty of opportunity to practice and hone in their underground homes.</li>\n <li>Weapon Familiarity: Dwarves treat dwarven waraxes and dwarven urgroshes as martial weapons, rather than exotic weapons.</li>\n <li>Stability: Dwarves are exceptionally stable on their feet. A dwarf has a +4 bonus on ability checks made to resist being bull rushed or tripped when standing on the ground (but not when climbing, flying, riding, or otherwise not standing firmly on the ground).</li>\n <li>+2 racial bonus on saving throws against poison. *Not reflected in the saving throw numbers given here.</li>\n <li>+2 racial bonus on saving throws against spells and spell-like effects. *Not reflected in the saving throw numbers given here.</li>\n <li>+1 racial bonus on attack rolls against orcs (including halforcs) and goblinoids (including goblins, hobgoblins, and bugbears).</li>\n <li>+4 dodge bonus to Armor Class against creatures of the giant type (such as ogres, trolls, and hill giants).</li>\n <li>+2 racial bonus on Appraise checks that are related to stone or metal items.</li>\n <li>+2 racial bonus on Craft checks that are related to stone or metal.</li>\n <li>Automatic Languages: Common, Dwarven. Bonus Languages: Giant, Gnome, Goblin, Orc, Terran, Undercommon.</li>\n <li>Favored Class: Fighter.</li>\n</ul><p>The dwarf warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Subraces\" level=\"3\"><p><h3>Subraces</h3></p><p>The information above is for hill dwarves, the most common variety.</p><p>There are three other major dwarven subraces, which differ from hill dwarves as follows.</p><div topic=\"Deep Dwarf\" level=\"5\"><p><h5><b>Deep Dwarf</b></h5></p><p>These dwarves live far underground and tend to be more standoffish with non-dwarves.</p><p>Deep dwarves are the same height as other dwarves, but leaner.  Their skin sometimes has a reddish tinge, and their large eyes lack the brightness of those of their kindred, being a washed-out blue. Their hair color ranges from bright red to straw blond. They have little contact with surface dwellers, relying on hill dwarves or mountain dwarves to trade goods for them.</p><p>Deep dwarves speak Dwarven and Goblin, and occasionally Draconic or Undercommon.</p><div topic=\"Deep Dwarf Traits\" level=\"8\"><p><b>Deep Dwarf Traits (Ex):</b> These traits are in addition to the hill dwarf traits, except where noted.</p><ul>\n <li>Racial bonus on saves against spells and spell-like abilities increases to +3.</li>\n <li>Racial bonus on Fortitude saves against poisons increases to +3.</li>\n <li>Darkvision out to 90 feet.</li>\n <li>Light Sensitivity: Deep dwarves are dazzled in bright sunlight or within the radius of a <i>daylight</i> spell.</li>\n</ul>\n</div>\n</div><div topic=\"Duergar\" level=\"5\"><p><h5><b>Duergar</b></h5></p><p>Sometimes called gray dwarves, these evil beings dwell in the underground.</p><p>Most duergar are bald (even the females), and they dress in drab clothing that is designed to blend into stone. In their lairs they may wear jewelry, but it is always kept dull. They war with other dwarves, even allying with other underground creatures from time to time.</p><p>Duergar speak Dwarven and Undercommon.</p><div topic=\"Duergar Traits\" level=\"8\"><p><b>Duergar Traits (Ex):</b> These traits are in addition to the hill dwarf traits, except where noted.</p><ul>\n <li>-4 Charisma instead of -2.</li>\n <li>Darkvision out to 120 feet.</li>\n <li>Immunity to paralysis, phantasms, and poison. This trait replaces the hill dwarf\'s +2 racial bonus on saving throws against poison.</li>\n <li>+2 racial bonus on saves against spells and spell-like abilities.</li>\n <li>Spell-Like Abilities: 1/day-<i>enlarge person</i> and <i>invisibility</i> as a wizard of twice the duergar\'s class level (minimum caster level 3rd); these abilities affect only the duergar and whatever it carries.</li>\n <li>Light Sensitivity: Duergar are dazzled in bright sunlight or within the radius of a <i>daylight</i> spell.</li>\n <li>+4 racial bonus on Move Silently checks.</li>\n <li>+1 racial bonus on Listen and Spot checks.</li>\n <li>Automatic Languages: Common, Dwarven, Undercommon.</li>\n</ul><p>Bonus Languages: Draconic, Giant, Goblin, Orc, Terran. This trait replaces the hill dwarf\'s automatic and bonus languages.</p><ul>\n <li>Favored Class: Fighter.</li>\n <li>Level adjustment +1</li>\n <li>Unlike other dwarves, duergar do not have weapon familiarity with the dwarven waraxe and dwarven urgrosh.</li>\n</ul><p>The duergar warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Duergar with levels in NPC classes have a CR equal to their character level. Duergar with levels in PC classes have a CR equal to their character level +1.</p>\n</div>\n</div><div topic=\"Mountain Dwarf\" level=\"5\"><p><h5><b>Mountain Dwarf</b></h5></p><p>Mountain dwarves live deeper under the mountains than hill dwarves but generally not as far underground as deep dwarves. They average about 4-1/2 feet tall and have lighter skin and hair than hill dwarves, but the same general appearance.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersDr-Dw');
INSERT INTO monster VALUES (334,'Dwarf','Duergar, 1st-Level Warrior',NULL,'Medium','Humanoid','Dwarf','1d8+5 (9 hp)','+0','20 ft. in chainmail (4 squares); base speed 20 ft.','17 (+5 chainmail, +2 heavy shield), touch 10, flat-footed 17','+1','+2','Warhammer +2 melee (1d8+1/x3) or light crossbow +1 ranged (1d8/19-20)','Warhammer +2 melee (1d8+1/x3) or light crossbow +1 ranged (1d8/19-20)','5 ft.','5 ft.','Duergar traits, spell-like abilities','Darkvision 60 ft., duergar traits','Fort +4*, Ref +0*, Will -1*','Str 13, Dex 11, Con 14, Int 10, Wis 9, Cha 4','Appraise +2, Craft (blacksmithing) +2, Craft (stonemasonry) +2, Listen +3, Move Silently -4, Spot +2',NULL,'Toughness',NULL,'Underground','Team (2-4), squad (9-16 plus 3 3rd-level sergeants and 1 leader of 3rd-8th level) or clan (20-80 plus 25% noncombatants plus 1 3rd-level sergeant per 5 adults, 3-6 6th-level lieutenants, and 1-4 9th-level captains)','1','Standard coins, double goods, standard items','Often lawful evil','By character class','+1','Duergar Traits (Ex), Dwarf Traits (Ex)','1st-level warrior duergar; CR 1; Medium humanoid (dwarf); HD 1d8+5; hp 9; Init +0; Spd 20 ft. in chainmail (4 squares); base speed 20 ft.; AC 17 (+5 chainmail, +2 heavy shield), touch 10, flat-footed 17; Base Atk +1; Grp +2; Atk +2 melee (1d8+1/x3, warhammer) or +1 ranged (1d8/19-20, light crossbow); Full Atk +2 melee (1d8+1/x3, warhammer) or +1 ranged (1d8/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA Duergar traits, spell-like abilities; SQ Darkvision 60 ft., duergar traits; AL LE; SV Fort +4*, Ref +0*, Will -1*; Str 13, Dex 11, Con 14, Int 10, Wis 9, Cha 4\n\nSkills and Feats: Appraise +2, Craft (blacksmithing) +2, Craft (stonemasonry) +2, Listen +3, Move Silently -4, Spot +2; Toughness','\n      <div topic=\"Dwarf\" level=\"2\"><p><h2>Dwarf</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n <td><b>Duergar, 1st-Level Warrior</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Medium Humanoid (Dwarf)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>1d8+5 (9 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>20 ft. in chainmail (4 squares); base speed 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>17 (+5 chainmail, +2 heavy shield), touch 10, flat-footed 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+1/+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Warhammer +2 melee (1d8+1/x3) or light crossbow +1 ranged (1d8/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Warhammer +2 melee (1d8+1/x3) or light crossbow +1 ranged (1d8/19-20)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Duergar traits, spell-like abilities<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Darkvision 60 ft., duergar traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +4*, Ref +0*, Will -1*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 13, Dex 11, Con 14, Int 10, Wis 9, Cha 4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Appraise +2, Craft (blacksmithing) +2, Craft (stonemasonry) +2, Listen +3, Move Silently -4, Spot +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n <td>Underground<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Team (2-4), squad (9-16 plus 3 3rd-level sergeants and 1 leader of 3rd-8th level) or clan (20-80 plus 25% noncombatants plus 1 3rd-level sergeant per 5 adults, 3-6 6th-level lieutenants, and 1-4 9th-level captains)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>Standard coins, double goods, standard items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n <td>Often lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>+1<br/></td>\n\n</tr>\n</table><p>Dwarves favor earth tones in their clothing and prefer simple and functional garb. The skin can be very dark, but it is always some shade of tan or brown. Hair color can be black, gray, or brown. Dwarves average 4 feet tall and weigh as much as adult humans.</p><p>Dwarves speak Dwarven. Most who travel outside dwarven lands (as traders, mercenaries, or adventurers) know the Common tongue, while warriors in the dwarven cities usually learn Goblin to better interrogate and spy on those evil denizens of the deep caves.</p><p>Most dwarves encountered outside their home are warriors.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Dwarves are experts in combat, effectively using their environment and executing well-planned group attacks. They rarely use magic in fights, since they have few wizards or sorcerers (but dwarven clerics throw themselves into battle as heartily as their fellow warriors). If they have time to prepare, they may build deadfalls or other traps involving stone. In addition to the dwarven waraxe and thrown hammer, dwarves also use warhammers, picks, shortbows, heavy crossbows, and maces.</p><div topic=\"Dwarf Traits\" level=\"8\"><p><b>Dwarf Traits (Ex):</b> Dwarves possess the following racial traits.</p><ul>\n <li>+2 Constitution, -2 Charisma.</li>\n <li>Medium size.</li>\n</ul><p>-A dwarf\'s base land speed is 20 feet. However, dwarves can move at this speed even when wearing medium or heavy armor or when carrying a medium or heavy load.</p><ul>\n <li>Darkvision out to to 60 feet.</li>\n <li>Stonecunning: This ability grants a dwarf a +2 racial bonus on Search checks to notice unusual stonework, such as sliding walls, stonework traps, new construction (even when built to match the old), unsafe stone surfaces, shaky stone ceilings, and the like. Something that isn\'t stone but that is disguised as stone also counts as unusual stonework. A dwarf who merely comes within 10 feet of unusual stonework can make a Search check as if he were actively searching, and a dwarf can use the Search skill to find stonework traps as a rogue can. A dwarf can also intuit depth, sensing his approximate depth underground as naturally as a human can sense which way is up. Dwarves have a sixth sense about stonework, an innate ability that they get plenty of opportunity to practice and hone in their underground homes.</li>\n <li>Weapon Familiarity: Dwarves treat dwarven waraxes and dwarven urgroshes as martial weapons, rather than exotic weapons.</li>\n <li>Stability: Dwarves are exceptionally stable on their feet. A dwarf has a +4 bonus on ability checks made to resist being bull rushed or tripped when standing on the ground (but not when climbing, flying, riding, or otherwise not standing firmly on the ground).</li>\n <li>+2 racial bonus on saving throws against poison. *Not reflected in the saving throw numbers given here.</li>\n <li>+2 racial bonus on saving throws against spells and spell-like effects. *Not reflected in the saving throw numbers given here.</li>\n <li>+1 racial bonus on attack rolls against orcs (including halforcs) and goblinoids (including goblins, hobgoblins, and bugbears).</li>\n <li>+4 dodge bonus to Armor Class against creatures of the giant type (such as ogres, trolls, and hill giants).</li>\n <li>+2 racial bonus on Appraise checks that are related to stone or metal items.</li>\n <li>+2 racial bonus on Craft checks that are related to stone or metal.</li>\n <li>Automatic Languages: Common, Dwarven. Bonus Languages: Giant, Gnome, Goblin, Orc, Terran, Undercommon.</li>\n <li>Favored Class: Fighter.</li>\n</ul><p>The dwarf warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div>\n</div><div topic=\"Subraces\" level=\"3\"><p><h3>Subraces</h3></p><p>The information above is for hill dwarves, the most common variety.</p><p>There are three other major dwarven subraces, which differ from hill dwarves as follows.</p><div topic=\"Deep Dwarf\" level=\"5\"><p><h5><b>Deep Dwarf</b></h5></p><p>These dwarves live far underground and tend to be more standoffish with non-dwarves.</p><p>Deep dwarves are the same height as other dwarves, but leaner.  Their skin sometimes has a reddish tinge, and their large eyes lack the brightness of those of their kindred, being a washed-out blue. Their hair color ranges from bright red to straw blond. They have little contact with surface dwellers, relying on hill dwarves or mountain dwarves to trade goods for them.</p><p>Deep dwarves speak Dwarven and Goblin, and occasionally Draconic or Undercommon.</p><div topic=\"Deep Dwarf Traits\" level=\"8\"><p><b>Deep Dwarf Traits (Ex):</b> These traits are in addition to the hill dwarf traits, except where noted.</p><ul>\n <li>Racial bonus on saves against spells and spell-like abilities increases to +3.</li>\n <li>Racial bonus on Fortitude saves against poisons increases to +3.</li>\n <li>Darkvision out to 90 feet.</li>\n <li>Light Sensitivity: Deep dwarves are dazzled in bright sunlight or within the radius of a <i>daylight</i> spell.</li>\n</ul>\n</div>\n</div><div topic=\"Duergar\" level=\"5\"><p><h5><b>Duergar</b></h5></p><p>Sometimes called gray dwarves, these evil beings dwell in the underground.</p><p>Most duergar are bald (even the females), and they dress in drab clothing that is designed to blend into stone. In their lairs they may wear jewelry, but it is always kept dull. They war with other dwarves, even allying with other underground creatures from time to time.</p><p>Duergar speak Dwarven and Undercommon.</p><div topic=\"Duergar Traits\" level=\"8\"><p><b>Duergar Traits (Ex):</b> These traits are in addition to the hill dwarf traits, except where noted.</p><ul>\n <li>-4 Charisma instead of -2.</li>\n <li>Darkvision out to 120 feet.</li>\n <li>Immunity to paralysis, phantasms, and poison. This trait replaces the hill dwarf\'s +2 racial bonus on saving throws against poison.</li>\n <li>+2 racial bonus on saves against spells and spell-like abilities.</li>\n <li>Spell-Like Abilities: 1/day-<i>enlarge person</i> and <i>invisibility</i> as a wizard of twice the duergar\'s class level (minimum caster level 3rd); these abilities affect only the duergar and whatever it carries.</li>\n <li>Light Sensitivity: Duergar are dazzled in bright sunlight or within the radius of a <i>daylight</i> spell.</li>\n <li>+4 racial bonus on Move Silently checks.</li>\n <li>+1 racial bonus on Listen and Spot checks.</li>\n <li>Automatic Languages: Common, Dwarven, Undercommon.</li>\n</ul><p>Bonus Languages: Draconic, Giant, Goblin, Orc, Terran. This trait replaces the hill dwarf\'s automatic and bonus languages.</p><ul>\n <li>Favored Class: Fighter.</li>\n <li>Level adjustment +1</li>\n <li>Unlike other dwarves, duergar do not have weapon familiarity with the dwarven waraxe and dwarven urgrosh.</li>\n</ul><p>The duergar warrior presented here had the following ability scores before racial adjustments: Str 13, Dex 11, Con 12, Int 10, Wis 9, Cha 8.</p>\n</div><div topic=\"Challenge Rating\" level=\"8\"><p><b>Challenge Rating:</b> Duergar with levels in NPC classes have a CR equal to their character level. Duergar with levels in PC classes have a CR equal to their character level +1.</p>\n</div>\n</div><div topic=\"Mountain Dwarf\" level=\"5\"><p><h5><b>Mountain Dwarf</b></h5></p><p>Mountain dwarves live deeper under the mountains than hill dwarves but generally not as far underground as deep dwarves. They average about 4-1/2 feet tall and have lighter skin and hair than hill dwarves, but the same general appearance.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersDr-Dw');
INSERT INTO monster VALUES (335,'Eagle, Giant','Eagle, Giant',NULL,'Large','Magical Beast',NULL,'4d10+4 (26 hp)','+3','10 ft. (2 squares), fly 80 ft. (average)','15 (-1 size, +3 Dex, +3 natural), touch 12, flat-footed 12','+4','+12','Claw +7 melee (1d6+4)','2 claws +7 melee (1d6+4) and bite +2 melee (1d8+2)','10 ft.','5 ft.','-','Low-light vision, evasion','Fort +5, Ref +7, Will +3','Str 18, Dex 17, Con 12, Int 10, Wis 14, Cha 10','Knowledge (nature) +2, Listen +6, Sense Motive +4, Spot +15, Survival +3',NULL,'Alertness, Flyby Attack',NULL,'Temperate mountains','Solitary, pair, or eyrie (5-12)','3','None','Usually neutral good','5-8 HD (Large); 9-12 HD (Huge)','+2 (cohort)','Evasion (Ex)','Giant eagle; CR 3; Large magical beast; HD 4d10+4; hp 26; Init +3; Spd 10 ft. (2 squares), fly 80 ft. (average); AC 15 (-1 size, +3 dex, +3 natural), touch 12, flat-footed 12; Base Atk +4; Grp +12; Atk +7 melee (1d6+4, claw); Full Atk +7 melee (1d6+4, 2 claws) and +2 melee (1d8+2, bite); Space/Reach 10 ft./5 ft.; SA -; SQ Low-light vision, evasion; AL NG; SV Fort +5, Ref +7, Will +3; Str 18, Dex 17, Con 12, Int 10, Wis 14, Cha 10\n\nSkills and Feats: Knowledge (nature) +2, Listen +6, Sense Motive +4, Spot +15, Survival +3; Alertness, Flyby Attack','\n      <div topic=\"Eagle, Giant\" level=\"2\"><p><h2>Eagle, Giant</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Eagle, Giant</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d10+4 (26 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>10 ft. (2 squares), fly 80 ft. (average)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (-1 size, +3 Dex, +3 natural), touch 12, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Claw +7 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 claws +7 melee (1d6+4) and bite +2 melee (1d8+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Low-light vision, evasion<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +7, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 18, Dex 17, Con 12, Int 10, Wis 14, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Knowledge (nature) +2, Listen +6, Sense Motive +4, Spot +15, Survival +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Flyby Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate mountains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or eyrie (5-12)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>5-8 HD (Large); 9-12 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+2 (cohort)<br/></td>\n\n</tr>\n</table><p>A typical giant eagle stands about 10 feet tall, has a wingspan of up to 20 feet, and resembles its smaller cousins in nearly every way except size. It weighs about 500 pounds.</p><p>Giant eagles speak Common and Auran.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>A giant eagle typically attacks from a great height, diving earthward at tremendous speed. When it cannot dive, it uses its powerful talons and slashing beak to strike at its target\'s head and eyes.</p><p>A solitary giant eagle is typically hunting or patrolling in the vicinity of its nest and generally ignores creatures that do not appear threatening. A mated pair attacks in concert, making repeated diving attacks to drive away intruders, and fights to the death to defend their nest or hatchlings.</p><div topic=\"Evasion\" level=\"8\"><p><b>Evasion (Ex):</b> With a successful Reflex save against an attack that allows a Reflex save for half damage, a giant eagle takes no damage.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Giant eagles have a +4 racial bonus on Spot checks.</p>\n</div>\n</div><div topic=\"Training A Giant Eagle\" level=\"3\"><p><h3>Training A Giant Eagle</h3></p><p>Although intelligent, a giant eagle requires training before it can bear a rider in combat. To be trained, a giant eagle must have a friendly attitude toward the trainer (this can be achieved through a successful Diplomacy check). Training a friendly giant eagle requires six weeks of work and a DC 25 Handle Animal check.</p><p>Riding a giant eagle requires an exotic saddle. A giant eagle can fight while carrying a rider, but the rider cannot also attack unless he or she succeeds on a Ride check.</p><p>Giant eagle eggs are worth 2,500 gp apiece on the open market, while chicks are worth 4,000 gp each. Professional trainers charge 1,000 gp to rear or train a giant eagle.</p><p>Carrying Capacity: A light load for a giant eagle is up to 300 pounds; a medium load, 301-600 pounds; and a heavy load, 601-900 pounds.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
INSERT INTO monster VALUES (336,'Elemental','Air Elemental, Small',NULL,'Small','Elemental','Air, Extraplanar','2d8 (9 hp)','+7','Fly 100 ft. (perfect) (20 squares)','17 (+1 size, +3 Dex, +3 natural), touch 14, flat-footed 14','+1','-3','Slam +5 melee (1d4)','Slam +5 melee (1d4)','5 ft.','5 ft.','Air mastery, whirlwind','Darkvision 60 ft., elemental traits','Fort +0, Ref +6, Will +0','Str 10, Dex 17, Con 10, Int 4, Wis 11, Cha 11','Listen +2, Spot +3','Improved Initiative, Weapon Finesse','Flyby Attack',NULL,'Elemental Plane of Air','Solitary','1','None','Usually neutral','3 HD (Small)','-','Air Mastery (Ex), Whirlwind (Su)','Small air elemental; CR 1; Small elemental (air, extraplanar); HD 2d8; hp 9; Init +7; Spd Fly 100 ft. (perfect) (20 squares); AC 17 (+1 size, +3 dex, +3 natural), touch 14, flat-footed 14; Base Atk +1; Grp -3; Atk +5 melee (1d4, slam); Full Atk +5 melee (1d4, slam); Space/Reach 5 ft./5 ft.; SA Air mastery, whirlwind; SQ Darkvision 60 ft., elemental traits; AL N; SV Fort +0, Ref +6, Will +0; Str 10, Dex 17, Con 10, Int 4, Wis 11, Cha 11\n\nSkills and Feats: Listen +2, Spot +3; Flyby Attack, Improved Initiative, Weapon Finesse','\n      <div topic=\"Air Elemental\" level=\"3\"><p><h3>Air Elemental</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Air Elemental, Small</b><br/></td> \n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Elemental (Air, Extraplanar)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>2d8 (9 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Fly 100 ft. (perfect) (20 squares)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>17 (+1 size, +3 Dex, +3 natural), touch 14, flat-footed 14<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +5 melee (1d4)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Slam +5 melee (1d4)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Air mastery, whirlwind<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., elemental traits<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +0, Ref +6, Will +0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 17, Con 10, Int 4, Wis 11, Cha 11<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Listen +2, Spot +3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Flyby Attack, Improved Initiative <sup>B</sup>, Weapon Finesse <sup>B</sup><br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Elemental Plane of Air<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>1<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>3 HD (Small)<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p/><p/><p>Air elementals speak Auran, though they rarely choose to do so.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Their rapid speed makes air elementals useful on vast battlefields or in extended aerial combat.</p><div topic=\"Air Mastery\" level=\"8\"><p><b>Air Mastery (Ex):</b> Airborne creatures take a -1 penalty on attack and damage rolls against an air elemental.</p>\n</div><div topic=\"Whirlwind\" level=\"8\"><p><b>Whirlwind (Su):</b> The elemental can transform itself into a whirlwind once every 10 minutes and remain in that form for up to 1 round for every 2 HD it has. In this form, the elemental can move through the air or along a surface at its fly speed.</p><p>The whirlwind is 5 feet wide at the base, up to 30 feet wide at the top, and up to 50 feet tall, depending on the elemental\'s size. The elemental controls the exact height, but it must be at least 10 feet.</p><p>The elemental\'s movement while in whirlwind form does not provoke attacks of opportunity, even if the elemental enters the space another creature occupies. Another creature might be caught in the whirlwind if it touches or enters the whirlwind, or if the elemental moves into or through the creature\'s space.</p><p>Creatures one or more size categories smaller than the elemental might take damage when caught in the whirlwind (see the table below for details) and may be lifted into the air. An affected creature must succeed on a Reflex save when it comes into contact with the whirlwind or take the indicated damage. It must also succeed on a second Reflex save or be picked up bodily and held suspended in the powerful winds, automatically taking the indicated damage each round. A creature that can fly is allowed a Reflex save each round to escape the whirlwind. The creature still takes damage but can leave if the save is successful. The DC for saves against the whirlwind\'s effects varies with the elemental\'s size (see the table). The save DC is Strength based.</p><p>Creatures trapped in the whirlwind cannot move except to go where the elemental carries them or to escape the whirlwind.</p><p>Creatures caught in the whirlwind can otherwise act normally, but must succeed on a Concentration check (DC 15 + spell level) to cast a spell. Creatures caught in the whirlwind take a -4 penalty to Dexterity and a -2 penalty on attack rolls. The elemental can have only as many creatures trapped inside the whirlwind at one time as will fit inside the whirlwind\'s volume.</p><p>The elemental can eject any carried creatures whenever it wishes, depositing them wherever the whirlwind happens to be. A summoned elemental always ejects trapped creatures before returning to its home plane.</p><p>If the whirlwind\'s base touches the ground, it creates a swirling cloud of debris. This cloud is centered on the elemental and has a diameter equal to half the whirlwind\'s height. The cloud obscures all vision, including darkvision, beyond 5 feet. Creatures 5 feet away have concealment, while those farther away have total concealment.</p><p>Those caught in the cloud must succeed on a Concentration check (DC 15 + spell level) to cast a spell.</p><p>An elemental in whirlwind form cannot make slam attacks and does not threaten the area around it.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"2\">\n<td colspan=\"6\"><b>Air Elemental Sizes</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"5\">\n<td/>\n<td/>\n<td/>\n<td colspan=\"3\" align=\"center\"><b>----- Whirlwind -----</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Save DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n<td><b>Height</b><br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>1 lb.<br/></td>\n<td>11<br/></td>\n<td>1d4<br/></td>\n<td>10-20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>2 lb.<br/></td>\n<td>13<br/></td>\n<td>1d6<br/></td>\n<td>10-30 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>4 lb.<br/></td>\n<td>16<br/></td>\n<td>2d6<br/></td>\n<td>10-40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>8 lb.<br/></td>\n<td>22<br/></td>\n<td>2d8<br/></td>\n<td>10-50 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>10 lb.<br/></td>\n<td>25<br/></td>\n<td>2d8<br/></td>\n<td>10-60 ft.<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>12 lb.<br/></td>\n<td>28<br/></td>\n<td>2d8<br/></td>\n<td>10-60 ft.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
INSERT INTO monster VALUES (337,'Elemental','Air Elemental, Medium',NULL,'Medium','Elemental','Air, Extraplanar','4d8+8 (26 hp)','+9','Fly 100 ft. (perfect) (20 squares)','18 (+5 Dex, +3 natural), touch 15, flat-footed 13','+3','+4','Slam +8 melee (1d6+1)','Slam +8 melee (1d6+1)','5 ft.','5 ft.','Air mastery, whirlwind','Darkvision 60 ft., elemental traits','Fort +3, Ref +9, Will +1','Str 12, Dex 21, Con 14, Int 4, Wis 11, Cha 11','Listen +3, Spot +4','Improved Initiative, Weapon Finesse','Dodge, Flyby Attack',NULL,'Elemental Plane of Air','Solitary','3','None','Usually neutral','5-7 HD (Medium)','-','Air Mastery (Ex), Whirlwind (Su)','Medium air elemental; CR 3; Medium elemental (air, extraplanar); HD 4d8+8; hp 26; Init +9; Spd Fly 100 ft. (perfect) (20 squares); AC 18 (+5 dex, +3 natural), touch 15, flat-footed 13; Base Atk +3; Grp +4; Atk +8 melee (1d6+1, slam); Full Atk +8 melee (1d6+1, slam); Space/Reach 5 ft./5 ft.; SA Air mastery, whirlwind; SQ Darkvision 60 ft., elemental traits; AL N; SV Fort +3, Ref +9, Will +1; Str 12, Dex 21, Con 14, Int 4, Wis 11, Cha 11\n\nSkills and Feats: Listen +3, Spot +4; Dodge, Flyby Attack, Improved Initiative, Weapon Finesse','\n      <div topic=\"Air Elemental\" level=\"3\"><p><h3>Air Elemental</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n <td><b>Air Elemental, Medium</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Medium Elemental (Air, Extraplanar)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>4d8+8 (26 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+9<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>Fly 100 ft. (perfect) (20 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>18 (+5 Dex, +3 natural), touch 15, flat-footed 13<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+3/+4<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Slam +8 melee (1d6+1)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Slam +8 melee (1d6+1)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>5 ft./5 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Air mastery, whirlwind<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Darkvision 60 ft., elemental traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +3, Ref +9, Will +1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 12, Dex 21, Con 14, Int 4, Wis 11, Cha 11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Listen +3, Spot +4<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Dodge, Flyby Attack, Improved Initiative <sup>B</sup>, Weapon Finesse <sup>B</sup><br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Elemental Plane of Air<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>3<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Usually neutral<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>5-7 HD (Medium)<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n</table><p/><p/><p>Air elementals speak Auran, though they rarely choose to do so.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Their rapid speed makes air elementals useful on vast battlefields or in extended aerial combat.</p><div topic=\"Air Mastery\" level=\"8\"><p><b>Air Mastery (Ex):</b> Airborne creatures take a -1 penalty on attack and damage rolls against an air elemental.</p>\n</div><div topic=\"Whirlwind\" level=\"8\"><p><b>Whirlwind (Su):</b> The elemental can transform itself into a whirlwind once every 10 minutes and remain in that form for up to 1 round for every 2 HD it has. In this form, the elemental can move through the air or along a surface at its fly speed.</p><p>The whirlwind is 5 feet wide at the base, up to 30 feet wide at the top, and up to 50 feet tall, depending on the elemental\'s size. The elemental controls the exact height, but it must be at least 10 feet.</p><p>The elemental\'s movement while in whirlwind form does not provoke attacks of opportunity, even if the elemental enters the space another creature occupies. Another creature might be caught in the whirlwind if it touches or enters the whirlwind, or if the elemental moves into or through the creature\'s space.</p><p>Creatures one or more size categories smaller than the elemental might take damage when caught in the whirlwind (see the table below for details) and may be lifted into the air. An affected creature must succeed on a Reflex save when it comes into contact with the whirlwind or take the indicated damage. It must also succeed on a second Reflex save or be picked up bodily and held suspended in the powerful winds, automatically taking the indicated damage each round. A creature that can fly is allowed a Reflex save each round to escape the whirlwind. The creature still takes damage but can leave if the save is successful. The DC for saves against the whirlwind\'s effects varies with the elemental\'s size (see the table). The save DC is Strength based.</p><p>Creatures trapped in the whirlwind cannot move except to go where the elemental carries them or to escape the whirlwind.</p><p>Creatures caught in the whirlwind can otherwise act normally, but must succeed on a Concentration check (DC 15 + spell level) to cast a spell. Creatures caught in the whirlwind take a -4 penalty to Dexterity and a -2 penalty on attack rolls. The elemental can have only as many creatures trapped inside the whirlwind at one time as will fit inside the whirlwind\'s volume.</p><p>The elemental can eject any carried creatures whenever it wishes, depositing them wherever the whirlwind happens to be. A summoned elemental always ejects trapped creatures before returning to its home plane.</p><p>If the whirlwind\'s base touches the ground, it creates a swirling cloud of debris. This cloud is centered on the elemental and has a diameter equal to half the whirlwind\'s height. The cloud obscures all vision, including darkvision, beyond 5 feet. Creatures 5 feet away have concealment, while those farther away have total concealment.</p><p>Those caught in the cloud must succeed on a Concentration check (DC 15 + spell level) to cast a spell.</p><p>An elemental in whirlwind form cannot make slam attacks and does not threaten the area around it.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"2\">\n<td colspan=\"6\"><b>Air Elemental Sizes</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"5\">\n<td/>\n<td/>\n<td/>\n<td colspan=\"3\" align=\"center\"><b>----- Whirlwind -----</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Save DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n<td><b>Height</b><br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>1 lb.<br/></td>\n<td>11<br/></td>\n<td>1d4<br/></td>\n<td>10-20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>2 lb.<br/></td>\n<td>13<br/></td>\n<td>1d6<br/></td>\n<td>10-30 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>4 lb.<br/></td>\n<td>16<br/></td>\n<td>2d6<br/></td>\n<td>10-40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>8 lb.<br/></td>\n<td>22<br/></td>\n<td>2d8<br/></td>\n<td>10-50 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>10 lb.<br/></td>\n<td>25<br/></td>\n<td>2d8<br/></td>\n<td>10-60 ft.<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>12 lb.<br/></td>\n<td>28<br/></td>\n<td>2d8<br/></td>\n<td>10-60 ft.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
INSERT INTO monster VALUES (338,'Elemental','Air Elemental, Large',NULL,'Large','Elemental','Air, Extraplanar','8d8+24 (60 hp)','+11','Fly 100 ft. (perfect) (20 squares)','20 (-1 size, +7 Dex, +4 natural), touch 16, flat-footed 13','+6','+12','Slam +12 melee (2d6+2)','2 slams +12 melee (2d6+2)','10 ft.','10 ft.','Air mastery, whirlwind','Damage reduction 5/-, darkvision 60 ft., elemental traits','Fort +5, Ref +13, Will +2','Str 14, Dex 25, Con 16, Int 6, Wis 11, Cha 11','Listen +5, Spot +6','Improved Initiative, Weapon Finesse','Combat Reflexes, Dodge, Flyby Attack',NULL,'Elemental Plane of Air','Solitary','5','None','Usually neutral','9-15 HD (Large)','-','Air Mastery (Ex), Whirlwind (Su)','Large air elemental; CR 5; Large elemental (air, extraplanar); HD 8d8+24; hp 60; Init +11; Spd Fly 100 ft. (perfect) (20 squares); AC 20 (-1 size, +7 dex, +4 natural), touch 16, flat-footed 13; Base Atk +6; Grp +12; Atk +12 melee (2d6+2, slam); Full Atk +12 melee (2d6+2, 2 slams); Space/Reach 10 ft./10 ft.; SA Air mastery, whirlwind; SQ Damage reduction 5/-, darkvision 60 ft., elemental traits; AL N; SV Fort +5, Ref +13, Will +2; Str 14, Dex 25, Con 16, Int 6, Wis 11, Cha 11\n\nSkills and Feats: Listen +5, Spot +6; Combat Reflexes, Dodge, Flyby Attack, Improved Initiative, Weapon Finesse','\n      <div topic=\"Air Elemental\" level=\"3\"><p><h3>Air Elemental</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n \n<td><b>Air Elemental, Large</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Large Elemental (Air, Extraplanar)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>8d8+24 (60 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>+11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>Fly 100 ft. (perfect) (20 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>20 (-1 size, +7 Dex, +4 natural), touch 16, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n\n<td>+6/+12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n\n<td>Slam +12 melee (2d6+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n\n<td>2 slams +12 melee (2d6+2)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n\n<td>Air mastery, whirlwind<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n\n<td>Damage reduction 5/-, darkvision 60 ft., elemental traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n\n<td>Fort +5, Ref +13, Will +2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n\n<td>Str 14, Dex 25, Con 16, Int 6, Wis 11, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n\n<td>Listen +5, Spot +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n\n<td>Combat Reflexes, Dodge, Flyby Attack, Improved Initiative <sup>B</sup>, Weapon Finesse <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n\n<td>Elemental Plane of Air<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n\n<td>9-15 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n\n<td>-<br/></td>\n\n</tr>\n</table><p/><p/><p>Air elementals speak Auran, though they rarely choose to do so.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Their rapid speed makes air elementals useful on vast battlefields or in extended aerial combat.</p><div topic=\"Air Mastery\" level=\"8\"><p><b>Air Mastery (Ex):</b> Airborne creatures take a -1 penalty on attack and damage rolls against an air elemental.</p>\n</div><div topic=\"Whirlwind\" level=\"8\"><p><b>Whirlwind (Su):</b> The elemental can transform itself into a whirlwind once every 10 minutes and remain in that form for up to 1 round for every 2 HD it has. In this form, the elemental can move through the air or along a surface at its fly speed.</p><p>The whirlwind is 5 feet wide at the base, up to 30 feet wide at the top, and up to 50 feet tall, depending on the elemental\'s size. The elemental controls the exact height, but it must be at least 10 feet.</p><p>The elemental\'s movement while in whirlwind form does not provoke attacks of opportunity, even if the elemental enters the space another creature occupies. Another creature might be caught in the whirlwind if it touches or enters the whirlwind, or if the elemental moves into or through the creature\'s space.</p><p>Creatures one or more size categories smaller than the elemental might take damage when caught in the whirlwind (see the table below for details) and may be lifted into the air. An affected creature must succeed on a Reflex save when it comes into contact with the whirlwind or take the indicated damage. It must also succeed on a second Reflex save or be picked up bodily and held suspended in the powerful winds, automatically taking the indicated damage each round. A creature that can fly is allowed a Reflex save each round to escape the whirlwind. The creature still takes damage but can leave if the save is successful. The DC for saves against the whirlwind\'s effects varies with the elemental\'s size (see the table). The save DC is Strength based.</p><p>Creatures trapped in the whirlwind cannot move except to go where the elemental carries them or to escape the whirlwind.</p><p>Creatures caught in the whirlwind can otherwise act normally, but must succeed on a Concentration check (DC 15 + spell level) to cast a spell. Creatures caught in the whirlwind take a -4 penalty to Dexterity and a -2 penalty on attack rolls. The elemental can have only as many creatures trapped inside the whirlwind at one time as will fit inside the whirlwind\'s volume.</p><p>The elemental can eject any carried creatures whenever it wishes, depositing them wherever the whirlwind happens to be. A summoned elemental always ejects trapped creatures before returning to its home plane.</p><p>If the whirlwind\'s base touches the ground, it creates a swirling cloud of debris. This cloud is centered on the elemental and has a diameter equal to half the whirlwind\'s height. The cloud obscures all vision, including darkvision, beyond 5 feet. Creatures 5 feet away have concealment, while those farther away have total concealment.</p><p>Those caught in the cloud must succeed on a Concentration check (DC 15 + spell level) to cast a spell.</p><p>An elemental in whirlwind form cannot make slam attacks and does not threaten the area around it.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"2\">\n<td colspan=\"6\"><b>Air Elemental Sizes</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"5\">\n<td/>\n<td/>\n<td/>\n<td colspan=\"3\" align=\"center\"><b>----- Whirlwind -----</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Save DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n<td><b>Height</b><br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>1 lb.<br/></td>\n<td>11<br/></td>\n<td>1d4<br/></td>\n<td>10-20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>2 lb.<br/></td>\n<td>13<br/></td>\n<td>1d6<br/></td>\n<td>10-30 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>4 lb.<br/></td>\n<td>16<br/></td>\n<td>2d6<br/></td>\n<td>10-40 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>8 lb.<br/></td>\n<td>22<br/></td>\n<td>2d8<br/></td>\n<td>10-50 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>10 lb.<br/></td>\n<td>25<br/></td>\n<td>2d8<br/></td>\n<td>10-60 ft.<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>12 lb.<br/></td>\n<td>28<br/></td>\n<td>2d8<br/></td>\n<td>10-60 ft.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
INSERT INTO monster VALUES (339,'Elemental','Air Elemental, Huge',NULL,'Huge','Elemental','Air, Extraplanar','16d8+64 (136 hp)','+13','Fly 100 ft. (perfect) (20 squares)','21 (-2 size, +9 Dex, +4 natural), touch 17, flat-footed 12','+12','+24','Slam +19 melee (2d8+4)','2 slams +19 melee (2d8+4)','15 ft.','15 ft.','Air mastery, whirlwind','Damage reduction 5/-, darkvision 60 ft., elemental traits','Fort +9, Ref +19, Will +5','Str 18, Dex 29, Con 18, Int 6, Wis 11, Cha 11','Listen +11, Spot +12','Improved Initiative, Weapon Finesse','Alertness, Combat Reflexes, Dodge, Flyby Attack, Mobility, Spring Attack',NULL,'Elemental Plane of Air','Solitary','7','None','Usually neutral','17-20 HD (Huge)','-','Air Mastery (Ex), Whirlwind (Su)','Huge air elemental; CR 7; Huge elemental (air, extraplanar); HD 16d8+64; hp 136; Init +13; Spd Fly 100 ft. (perfect) (20 squares); AC 21 (-2 size, +9 dex, +4 natural), touch 17, flat-footed 12; Base Atk +12; Grp +24; Atk +19 melee (2d8+4, slam); Full Atk +19 melee (2d8+4, 2 slams); Space/Reach 15 ft./15 ft.; SA Air mastery, whirlwind; SQ Damage reduction 5/-, darkvision 60 ft., elemental traits; AL N; SV Fort +9, Ref +19, Will +5; Str 18, Dex 29, Con 18, Int 6, Wis 11, Cha 11